function paperTerms(){const catalog=D.credit[$('p-kind').value]||{};options('p-product',[['all','Усі продукти'],...Object.keys(catalog).sort((a,b)=>a.localeCompare(b,'uk-UA')).map(name=>[name,name])],$('p-product')?.value);options('p-term',[['all','Усі строки'],...[...new Set(Object.values(catalog).map(p=>p.months))].sort((a,b)=>a-b).map(n=>[String(n),`${n} міс.`])],$('p-term')?.value);refreshCustomDropdowns();}
function renderPaper(){
 try{
  const price=read('p-price'),down=read('p-down'),extra=read('p-extra'),catalog=D.credit[$('p-kind').value],term='all',productFilter=$('p-product')?.value||'all';
  C.installment(price,down,1,'0');
  const available=[],unavailable=[];
  for(const [productName,product] of Object.entries(catalog)){
   if(productFilter!=='all'&&productName!==productFilter)continue;
   if(term!=='all'&&product.months!==Number(term))continue;
   for(const [bankName,bank] of Object.entries(product.banks)){
    if(price-down>C.toCents(bank.max_amount)){unavailable.push(`${productName} · ${bankName}: ліміт ${money(C.toCents(bank.max_amount))}`);continue;}
    const r=C.paper(price,down,product,bank);let added=null;
    if(price+extra-down<=C.toCents(bank.max_amount))added=C.paper(price+extra,down,product,bank);
    available.push({bankName,productName,product,bank,r,added});
   }
  }
  available.sort((a,b)=>a.r.monthly-b.r.monthly||Number(a.bank.commission_percent)-Number(b.bank.commission_percent)||a.r.sms-b.r.sms||a.r.months-b.r.months||a.productName.localeCompare(b.productName)||a.bankName.localeCompare(b.bankName));
  const rows=available.map(x=>[`${x.bankName} · ${x.productName}`,`${x.r.months} міс.`,`${x.bank.commission_percent}% · ${money(x.r.commission)}`,`${money(x.r.sms)} (${x.bank.sms_mode==='monthly'?money(C.toCents(x.bank.sms_amount))+' / міс.':'разово'})`,money(x.r.monthly),x.added?money(x.added.monthly):'Перевищено ліміт',money(x.r.over),money(x.r.total)]);
  tableRows('p-results',rows);
  if(!rows.length){const tr=node('tr'),td=node('td','Немає доступних пропозицій. Змініть суму, внесок або строк.');td.colSpan=8;tr.append(td);$('p-results').append(tr);}
  text('p-count',`${available.length} пропозицій`);text('p-unavailable',unavailable.length?'Недоступні за сумою: '+unavailable.join(' • '):'');
  text('p-context',`${$('p-kind').selectedOptions[0].textContent} · Покупка ${money(price)} · Внесок ${money(down)} · Кредит ${money(price-down)} · Доповнення ${money(extra)}.`);
  exports.paper=[['Паперові кредити',$('p-kind').selectedOptions[0].textContent],['Покупка',money(price)],['Внесок',money(down)],['Доповнення',money(extra)],['Банк / продукт','Строк','Комісія','SMS за весь строк','Середній / міс.','З доповненнями / міс.','Переплата','Разом із внеском'],...rows];
  error('p-error');buttons('paper',!rows.length);save();
 }catch(e){error('p-error',e.message);$('p-results').replaceChildren();text('p-count','');text('p-context','');text('p-unavailable','');exports.paper=[];buttons('paper',true);}
}
