function setupReceiptFinance(){const type=$('receipt-finance-type'),bank=$('receipt-finance-bank'),product=$('receipt-finance-product'),term=$('receipt-finance-term');if(!type)return;const fill=()=>{const mode=type.value;if(mode==='installment'){const entries=Object.entries(D.credit.installment_banks||{});options('receipt-finance-bank',entries.map(([name])=>[name,name]));const config=D.credit.installment_banks[bank.value]||entries[0]?.[1];options('receipt-finance-term',Object.entries(config?.payment_options||{}).map(([months,rate])=>[months,`${months} платежів · ${rate}%`]));$('receipt-finance-product-field').hidden=true;}else{const catalog=mode==='paper_regular'?D.credit.regular_credit_products:D.credit.promo_credit_products;options('receipt-finance-product',Object.keys(catalog).map(name=>[name,name]));const current=catalog[product.value]||catalog[Object.keys(catalog)[0]];options('receipt-finance-bank',Object.keys(current?.banks||{}).map(name=>[name,name]));const selected=current?.banks?.[bank.value]||Object.values(current?.banks||{})[0];options('receipt-finance-term',current?[String(current.months),`${current.months} міс.`]:[]);$('receipt-finance-product-field').hidden=false;}refreshCustomDropdowns();};type.addEventListener('change',fill);bank.addEventListener('change',fill);product.addEventListener('change',fill);fill();enhanceDropdown('receipt-finance-type');enhanceDropdown('receipt-finance-bank');enhanceDropdown('receipt-finance-product');enhanceDropdown('receipt-finance-term');};
function receiptFinanceCalculate(){const mode=$('receipt-finance-type')?.value,total=receiptTotalCents(),down=C.toCents($('receipt-finance-down')?.value||0);if(!total)return;text('receipt-finance-result','');try{if(mode==='installment'){const lines=[];for(const [bankName,config] of Object.entries(D.credit.installment_banks||{}))for(const [months,rate] of Object.entries(config.payment_options||{})){const result=C.installment(total,down,Number(months),rate);lines.push(`Банк: ${bankName}\n${months} платежів · Комісія: ${rate}% (${money(result.commission)}) · Платіж: ${money(result.monthly)} / міс. · Разом: ${money(result.total)}`);}text('receipt-finance-result',lines.join('\n\n'));}else{const productName=$('receipt-finance-product').value,catalog=mode==='paper_regular'?D.credit.regular_credit_products:D.credit.promo_credit_products,product=catalog[productName],lines=[];for(const [bankName,bank] of Object.entries(product?.banks||{})){const result=C.paper(total,down,product,bank);lines.push(`Банк: ${bankName} · Продукт: ${productName}\nСтрок: ${result.months} міс. · Комісія: ${bank.commission_percent}% (${money(result.commission)}) · SMS-комісія: ${money(result.sms)} · Платіж: ${money(result.monthly)} / міс. · Разом: ${money(result.total)}`);}text('receipt-finance-result',lines.join('\n\n'));}}catch(error){text('receipt-finance-result',error.message);}}
function receiptCartData(){try{return JSON.parse(localStorage.getItem('payment-desk-receipt-cart')||'[]')}catch{return[]}}
function renderReceiptCart(){const cart=receiptCartData(),panel=$('receipt-cart-panel'),list=$('receipt-cart-list'),open=$('[data-receipt-cart-open]');if(open)open.textContent=`Кошик (${cart.length})`;if(!panel||!list)return;list.replaceChildren(...(cart.length?cart.map((receipt,index)=>{const row=node('div',undefined,'receipt-cart-item'),date=new Date(receipt.createdAt).toLocaleString('uk-UA'),info=node('div',undefined,'receipt-cart-info');info.append(node('strong',`Чек від ${date}`),node('span',`${receipt.items.length+receipt.devices.length} позицій · ${money(receipt.total||0)}`));const load=node('button','Відкрити','secondary');load.type='button';load.addEventListener('click',()=>{receiptItems=JSON.parse(JSON.stringify(receipt.items||[]));receiptDevices=JSON.parse(JSON.stringify(receipt.devices||[]));receiptRenderDevices();receiptRender();panel.hidden=true;receiptStatus('Чек відкрито з кошика.');});const remove=node('button','🗑️','receipt-remove');remove.type='button';remove.addEventListener('click',()=>{const next=receiptCartData();next.splice(index,1);localStorage.setItem('payment-desk-receipt-cart',JSON.stringify(next));renderReceiptCart();});row.append(info,load,remove);return row;}):[node('p','Кошик порожній.','receipt-cart-empty')]));}
function receiptRender(){const host=$('receipt-items');if(!host)return;host.replaceChildren(...receiptItems.map((item,index)=>{const row=node('div',undefined,'receipt-row');const sku=node('input');sku.type='text';sku.placeholder='Артикул';sku.value=item.sku;sku.setAttribute('aria-label','Артикул');const lookup=node('button','Знайти','receipt-lookup');lookup.type='button';lookup.addEventListener('click',()=>receiptLookup(item,lookup));const name=node('input');name.type='text';name.placeholder='Назва товару';name.value=item.name;name.setAttribute('aria-label','Назва товару');const qty=node('input');qty.type='number';qty.min='1';qty.step='1';qty.value=item.qty;qty.setAttribute('aria-label','Кількість');const price=node('input');price.type='number';price.min='0';price.step='0.01';price.placeholder='0,00';price.value=item.price;price.setAttribute('aria-label','Ціна');const total=node('span',money((Number(item.qty)||0)*C.toCents(item.price||0)),'receipt-row-total');const remove=node('button','🗑️','receipt-remove');remove.type='button';remove.disabled=receiptItems.length===1;sku.addEventListener('input',()=>{item.sku=sku.value});name.addEventListener('input',()=>{item.name=name.value});qty.addEventListener('input',()=>{item.qty=qty.value;receiptUpdateTotal()});qty.addEventListener('change',()=>{item.qty=Math.max(1,Number(qty.value)||1);qty.value=item.qty;receiptUpdateTotal()});price.addEventListener('input',()=>{item.price=price.value;receiptUpdateTotal()});remove.addEventListener('click',()=>{receiptItems.splice(index,1);receiptRender()});row.append(sku,lookup,name,qty,price,total,remove);return row;}));receiptUpdateTotal();}
